+        }
+        if (this.dataStreams != null) {
+            builder.field("data_streams", this.dataStreams);
+        }
+        if (this.composableTemplates != null) {
+            builder.field("composable_templates", this.composableTemplates);
+        }
+        builder.endObject();
+        return builder;
+    }
+
+    @Override
